import{_ as t,o as s,c as a,a2 as o}from"./chunks/framework.BZO4qERu.js";const u=JSON.parse('{"title":"Workspace","description":"","frontmatter":{},"headers":[],"relativePath":"guides/container.md","filePath":"guides/container.md","lastUpdated":1792323081000}'),r={name:"guides/container.md"};function n(i,e,l,d,h,c){return s(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="workspace" tabindex="-1">Workspace <a class="header-anchor" href="#workspace" aria-label="Permalink to &quot;Workspace&quot;">​</a></h1><p>Every bot has its own <strong>workspace</strong> — a computer that belongs to it: a real filesystem, a terminal that executes commands, a preinstalled toolchain, and optionally a visible desktop. The files you hand the bot, the results it produces, and the tools it installs all live here, preserved across sessions.</p><h2 id="what-it-can-do" tabindex="-1">What it can do <a class="header-anchor" href="#what-it-can-do" aria-label="Permalink to &quot;What it can do&quot;">​</a></h2><ul><li>Store and edit files — browse them any time on the <strong>Files</strong> tab</li><li>Run scripts and install packages: <strong>Node.js</strong> and <strong>Python</strong> come preinstalled (<code>pip</code> and <code>uv</code> on PATH), no interpreter setup needed</li><li>Keep background tasks running</li><li>Preserve state across sessions — yesterday&#39;s unfinished work continues today</li><li>Optionally run a visible desktop with a headed browser</li></ul><h2 id="where-it-lives-in-the-client" tabindex="-1">Where it lives in the client <a class="header-anchor" href="#where-it-lives-in-the-client" aria-label="Permalink to &quot;Where it lives in the client&quot;">​</a></h2><p>Several tabs on the bot detail page face the workspace:</p><table tabindex="0"><thead><tr><th>Tab</th><th>Content</th></tr></thead><tbody><tr><td><strong>Workspace</strong></td><td>Workspace state and lifecycle: create, start, stop; runtime info, snapshots, import/export</td></tr><tr><td><strong>Files</strong></td><td>Browse and edit the workspace filesystem</td></tr><tr><td><strong>Terminal</strong></td><td>Open an interactive shell inside the workspace</td></tr><tr><td><strong>Desktop</strong></td><td>The visible desktop: live view, take over / hand back keyboard and mouse</td></tr><tr><td><strong>Network</strong></td><td>Workspace network status</td></tr><tr><td><strong>Apps</strong></td><td>Apps installed into this workspace — skills, dependencies, connectors (see <a href="./supermarket.html">Supermarket</a>)</td></tr></tbody></table><h2 id="lifecycle" tabindex="-1">Lifecycle <a class="header-anchor" href="#lifecycle" aria-label="Permalink to &quot;Lifecycle&quot;">​</a></h2><p>Managed from the <strong>Workspace</strong> tab:</p><ul><li><strong>Create</strong>: builds a new workspace from the template, with progress shown.</li><li><strong>Start / Stop</strong>: stop it to save resources when idle — nothing is lost.</li><li><strong>Delete</strong>: removes the running instance.</li></ul><p>Most capabilities — terminal, desktop, installing and updating Apps — need the workspace <strong>running</strong>. The tab also shows runtime info such as state, image, and background task count.</p><h2 id="the-visible-desktop" tabindex="-1">The visible desktop <a class="header-anchor" href="#the-visible-desktop" aria-label="Permalink to &quot;The visible desktop&quot;">​</a></h2><p>The <strong>Desktop</strong> tab enables and inspects the graphical desktop. Once on, the bot can drive a <strong>headed browser</strong> inside the workspace, and the desktop pane shows the same screen it operates:</p><ul><li>Watch every step live</li><li><strong>Take over</strong> the keyboard and mouse any time — type a password, pass a CAPTCHA — then <strong>hand control back</strong></li><li>Browser sessions persist in the workspace, so the next task is already signed in</li></ul><p>For the tool-level distinction, see <a href="./browser-computer-use.html">Browser / Computer Use</a>.</p><h2 id="snapshots" tabindex="-1">Snapshots <a class="header-anchor" href="#snapshots" aria-label="Permalink to &quot;Snapshots&quot;">​</a></h2><p><strong>Create Snapshot</strong> records the current workspace state — a rollback point before a big change; <strong>Restore</strong> reverts to a chosen snapshot, and unwanted snapshots can be deleted.</p><h2 id="import-and-export" tabindex="-1">Import and export <a class="header-anchor" href="#import-and-export" aria-label="Permalink to &quot;Import and export&quot;">​</a></h2><ul><li><strong>Export Data</strong>: package the workspace files for download.</li><li><strong>Import Data</strong>: upload an archive and unpack it into the workspace.</li><li><strong>Reset</strong>: return the data directory to a clean state — for when the filesystem is wrecked or you want a fresh start.</li></ul><div class="tip custom-block"><p class="custom-block-title">Self-hosting</p><p>Which runtime the workspace runs on (containerd, Docker, Apple container, a trusted local directory) and how host devices such as GPUs are passed through are server-side deployment concerns — see <a href="./../self-hosted/workspace-backends.html">Workspace Backends</a>. Memoh Cloud users never need to touch these.</p></div>',20)])])}const g=t(r,[["render",n]]);export{u as __pageData,g as default};
